using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysAtMost95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetExportedTypes()
            .Concat(typeof(DomainMarker).Assembly.GetExportedTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing") || t.Name.Contains("Customer"))
            .ToList();

        Assert.True(checkoutTypes.Count > 0,
            "No checkout/pricing/customer type exists, so a Gold customer's 100.00 subtotal cannot yield the approved 95.00 total.");
    }
}
